import type { SecretProvisioner } from '@twake/telephony-provider-sdk'
import { decrypt, encrypt, generateSecret } from './crypto.js'
import type { Store } from './store/types.js'

export interface SipSecretsOptions {
  store: Store
  key: Buffer
  provisioner: SecretProvisioner
}

/**
 * One random SIP secret per user, generated by the Gateway, pushed to the PBX and kept encrypted in the
 * database. There is no shared or default password, and no secret lives in a Cozy doctype or in the frontend:
 * the browser only receives it through the authenticated media-session call.
 */
export class SipSecrets {
  private readonly inflight = new Map<string, Promise<string>>()

  constructor(private readonly opts: SipSecretsOptions) {}

  /** Returns the user's secret, creating and provisioning it on first use. Concurrent calls share one creation. */
  getOrCreate(tenantId: string, userId: string, extension: string): Promise<string> {
    const k = `${tenantId}\u0000${userId}`
    const running = this.inflight.get(k)
    if (running) return running
    const task = this.load(tenantId, userId, extension).finally(() => this.inflight.delete(k))
    this.inflight.set(k, task)
    return task
  }

  /** Generates a new secret, provisions it, then stores it. Registered windows keep working until they re-register. */
  rotate(tenantId: string, userId: string, extension: string): Promise<string> {
    return this.create(tenantId, userId, extension)
  }

  private async load(tenantId: string, userId: string, extension: string) {
    const stored = await this.opts.store.getSipSecret(tenantId, userId)
    if (!stored) return this.create(tenantId, userId, extension)
    const secret = decrypt(stored.secretEnc, this.opts.key)
    // Provisioned again each time (an idempotent upsert): a user moved to another extension, or a PBX whose
    // account table was recreated, gets the hashes back without a new secret.
    await this.opts.provisioner.setSipSecret(extension, secret)
    return secret
  }

  private async create(tenantId: string, userId: string, extension: string) {
    const secret = generateSecret()
    // Provision first: a secret stored but unknown to the PBX would lock the user out.
    await this.opts.provisioner.setSipSecret(extension, secret)
    await this.opts.store.setSipSecret(tenantId, userId, encrypt(secret, this.opts.key))
    return secret
  }
}
